  "components-actions-link": {"name":"Link","title":"Components/Triggers/Link","category":"Components/Triggers","description":"Use Link for navigation and Button for actions. It renders a native anchor with normal browser behavior, including modifier-click and context menus. Disabled links have no destination and leave the tab sequence. External links open a new tab by default, announce that behavior, and include noopener/noreferrer. Keep link text descriptive; size changes text, not a button-like hit area.","kind":"component","aliases":["anchor","hyperlink","navigation link"]},
