  "patterns-filterbar": {"name":"FilterBar","title":"Patterns/Filtering/FilterBar","category":"Patterns/Filtering","description":"Choose one editing mode. Panel mode keeps search and table controls in the toolbar and edits facets in the sidebar; removable applied chips appear only while that sidebar is closed. Bar mode uses one compact filter picker and never opens a sidebar. Neither mode exposes unused facet options or saved-filter controls. Search is capped at 500px and shrinks with its container.","kind":"pattern","aliases":["applied filters","filter toolbar"]},
